+  <body>
+    <a class="skip-link" href="#main-content">Skip to main content</a>
+    <div id="app"></div>
+    <script>
+      const quizData = [
+        {
+          id: "question-1",
+          legend: "1. Which of these are programming languages commonly used for web development?",
+          helpText: "Select every answer you believe fits. More than one choice is correct.",
+          choices: ["JavaScript", "Python", "HTML", "Rust"]
+        },
+        {
+          id: "question-2",
+          legend: "2. Which languages are primarily compiled before running in many common workflows?",
+          choices: ["C++", "Java", "TypeScript", "CSS"]
+        },
+        {
+          id: "question-3",
+          legend: "3. Which languages are often used for systems or low-level programming tasks?",
+          choices: ["C", "Rust", "Ruby", "Assembly"]
+        }
+      ];
+
+      const state = {
+        answers: Object.fromEntries(quizData.map((question) => [question.id, []])),
+        errors: {},
+        submitted: false
+      };
+
+      function escapeHtml(value) {
+        return value
+          .replaceAll("&", "&amp;")
+          .replaceAll("<", "&lt;")
+          .replaceAll(">", "&gt;")
+          .replaceAll('"', "&quot;")
+          .replaceAll("'", "&#39;");
+      }
+
+      function App() {
+        return `
+          <header class="page-shell">
+            <p>Dark mode quiz</p>
+          </header>
+          <main id="main-content" class="page-shell">
+            <h1>Computer Languages Quiz</h1>
+            <p class="intro">
+              Answer all three questions. Each question supports multiple selections.
+            </p>
+            ${QuizForm()}
+          </main>
+          <footer class="page-shell">
+            <p>Choose the answers that best match each prompt.</p>
+          </footer>
+        `;
+      }
+
+      function QuizForm() {
+        return `
+          <form class="quiz-card" novalidate>
+            ${quizData.map((question, index) => QuestionField(question, index)).join("")}
+            <div class="actions">
+              <button type="submit">Submit quiz</button>
+            </div>
+            ${SubmissionStatus()}
+          </form>
+        `;
+      }
+
+      function QuestionField(question, index) {
+        const helpId = question.helpText ? `${question.id}-help` : "";
+        const errorId = `${question.id}-error`;
+        const hasError = Boolean(state.errors[question.id]);
+        const describedBy = [helpId, hasError ? errorId : ""].filter(Boolean).join(" ");
+
+        return `
+          <div class="form-field">
+            <fieldset aria-describedby="${describedBy}">
+              <legend>${escapeHtml(question.legend)}</legend>
+              ${question.helpText ? `<p id="${helpId}" class="question-help">${escapeHtml(question.helpText)}</p>` : ""}
+              ${hasError ? `<p id="${errorId}" class="error-message">${escapeHtml(state.errors[question.id])}</p>` : ""}
+              <div class="choice-list">
+                ${question.choices.map((choice) => ChoiceOption(question, choice, index)).join("")}
+              </div>
+            </fieldset>
+          </div>
+        `;
+      }
+
+      function ChoiceOption(question, choice, questionIndex) {
+        const inputId = `${question.id}-choice-${question.choices.indexOf(choice)}`;
+        const checked = state.answers[question.id].includes(choice) ? "checked" : "";
+        const invalid = state.errors[question.id] ? "true" : "false";
+
+        return `
+          <label class="choice" for="${inputId}">
+            <input
+              id="${inputId}"
+              type="checkbox"
+              name="${question.id}"
+              value="${escapeHtml(choice)}"
+              data-question-index="${questionIndex}"
+              ${checked}
+              aria-invalid="${invalid}"
+            />
+            <span class="choice-label">${escapeHtml(choice)}</span>
+          </label>
+        `;
+      }
+
+      function SubmissionStatus() {
+        if (!state.submitted || Object.keys(state.errors).length > 0) {
+          return '<div aria-live="polite"></div>';
+        }
+
+        const answerSummary = quizData
+          .map((question) => {
+            const selected = state.answers[question.id].join(", ");
+            return `<strong>${escapeHtml(question.legend)}</strong> ${escapeHtml(selected)}`;
+          })
+          .join("<br />");
+
+        return `
+          <div class="status-message" aria-live="polite">
+            Your selections were submitted.<br />${answerSummary}
+          </div>
+        `;
+      }
+
+      function renderApp() {
+        document.getElementById("app").innerHTML = App();
+        const form = document.querySelector("form");
+        form.addEventListener("change", handleChange);
+        form.addEventListener("submit", handleSubmit);
+      }
+
+      function handleChange(event) {
+        if (event.target.type !== "checkbox") {
+          return;
+        }
+
+        const { name, value, checked } = event.target;
+        const current = state.answers[name];
+
+        state.answers[name] = checked
+          ? [...current, value]
+          : current.filter((item) => item !== value);
+
+        if (state.errors[name] && state.answers[name].length > 0) {
+          delete state.errors[name];
+        }
+
+        renderApp();
+      }
+
+      function handleSubmit(event) {
+        event.preventDefault();
+        const errors = {};
+
+        quizData.forEach((question) => {
+          if (state.answers[question.id].length === 0) {
+            errors[question.id] = "Choose at least one answer before submitting.";
+          }
+        });
+
+        state.errors = errors;
+        state.submitted = true;
+        renderApp();
+
+        if (Object.keys(errors).length > 0) {
+          const firstInvalidQuestionId = quizData.find((question) => errors[question.id]).id;
+          const firstInvalidInput = document.querySelector(`input[name="${firstInvalidQuestionId}"]`);
+          if (firstInvalidInput) {
+            firstInvalidInput.focus();
+          }
+        }
+      }
+
+      renderApp();
+    </script>
+  </body>
